$aiJobsBefore=(int)$pdo->query('SELECT COUNT(*) FROM ai_jobs')->fetchColumn();$aiRunsBefore=(int)$pdo->query('SELECT COUNT(*) FROM ai_runs')->fetchColumn();$modelRun=data_evaluation_run_queue($pdo,$admin,$modelSuite['public_id']);$aiJobsAfter=(int)$pdo->query('SELECT COUNT(*) FROM ai_jobs')->fetchColumn();$aiRunsAfter=(int)$pdo->query('SELECT COUNT(*) FROM ai_runs')->fetchColumn();$modelSnapshot=json_decode((string)$modelRun['model_snapshot_json'],true)?:[];
